mapper.update:
update project_time set project_id = #{project.id}, date = #{date}, end_date = #{endDate}, start_time = #{startTime},
end_time = #{endTime}, schedule_name = #{scheduleName}, description = #{description}, week_id = #{weekId}
where id = #{id}

mapper.select:
select a.*
from project_time a
         join record_week b on a.week_id = b.id and b.user_id = #{userId}
where a.date >= #{startDate}
  and a.date <= #{endDate}

select pt.*
from project_time pt join record_week rw on pt.week_id = rw.id
where rw.user_id = #{userId}
  and pt.date < #{endDate}
  and coalesce(pt.end_date, pt.date) >= #{startDate}
